import React from 'react';

import {
  mapQuestionBaseToBack,
  mapQuestionInputParamsToBack,
} from '@apps/Interview/@mappers/interview.mapper';
import {
  addOrUpdateQuestionBase,
  addOrUpdateQuestionDirParam,
  addOrUpdateQuestionInputParam,
  addOrUpdateQuestionSelectVariants,
} from '@apps/Interview/@services/interview.service';
import {
  IQuestion,
  IQuestionDir,
  IQuestionInput,
  IQuestionSelect,
  IQuestionType,
} from '@apps/Interview/@types/interview.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

import EditQuestionDir from './EditQuestionDir';
import EditQuestionInput from './EditQuestionInput';
import EditQuestionOptions from './EditQuestionOptions';

interface IEditQuestionProps {
  iv_id: number;
  data: IQuestion;
  onSave: (data: IQuestion) => void;
}

const EditQuestion: React.FC<IEditQuestionProps> = ({ data, iv_id, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);

  const [error, setError] = React.useState<Error>();
  const [addData, setAddData] = React.useState<IQuestion>(data);

  const handleInputChange =
    <T extends IQuestion, K extends keyof T>(field: keyof T) =>
    (value: T[K]) => {
      setAddData((fd) => ({
        ...(fd as T),
        [field]: value,
      }));
    };

  return (
    <form
      style={{ minWidth: 420 }}
      onSubmit={async (e) => {
        e.preventDefault();
        try {
          setIsLoading(true);
          const up = { ...addData };
          if (!addData.id) {
            const id = await addOrUpdateQuestionBase(mapQuestionBaseToBack(addData, iv_id));
            up.id = id;
          } else {
            await addOrUpdateQuestionBase(mapQuestionBaseToBack(addData, iv_id));
          }

          if (addData.type === IQuestionType.Input) {
            const paramId = await addOrUpdateQuestionInputParam(
              mapQuestionInputParamsToBack((up as IQuestionInput).params, up.id),
            );
            (up as IQuestionInput).params.id = paramId;
          } else if (addData.type === IQuestionType.Select) {
            const newOptions = await addOrUpdateQuestionSelectVariants(
              up.id,
              (up as IQuestionSelect).options.map((o) => ({
                name: o.value,
                index: o.order_index,
              })),
            );
            (up as IQuestionSelect).options = newOptions.map((o) => ({
              id: +o.id,
              value: o.value,
              order_index: +o.order_index,
            }));
          } else if (addData.type === IQuestionType.Dir) {
            const dirId = await addOrUpdateQuestionDirParam({
              id: (up as IQuestionDir).dir.id,
              id_qq: up.id,
              id_dir: (up as IQuestionDir).dir.id_dir,
            });
            (up as IQuestionDir).dir.id = dirId;
          }
          onSave(up);
        } catch (er) {
          setError(er as Error);
        } finally {
          setIsLoading(false);
        }
      }}
    >
      <PohInput
        horizontal
        required
        label="Название"
        value={addData.name}
        onChange={handleInputChange('name')}
        placeholder="Название"
        disabled={isLoading}
      />
      <PohInput
        horizontal
        required
        label="Описание"
        value={addData.text}
        onChange={handleInputChange('text')}
        placeholder="Описание"
        disabled={isLoading}
        type={InputTypes.textarea}
      />

      <PohRow>
        <PohCol sm={2}></PohCol>
        <PohCol sm={10}>
          <PohCheckbox
            label="Обязательно для заполнения"
            checked={addData.isRequire}
            onChange={handleInputChange('isRequire')}
            disabled={isLoading}
          />

          <PohCheckbox
            label="Не показывать в статистике"
            checked={addData.isPrivate}
            onChange={handleInputChange('isPrivate')}
            disabled={isLoading}
          />
          {addData.type === IQuestionType.Select && (
            <>
              <PohCheckbox
                label="Выбирать несколько"
                checked={addData.isMulti}
                onChange={handleInputChange('isMulti')}
                disabled={isLoading}
              />

              <PohCheckbox
                label="Свой вариант"
                checked={addData.isCustom}
                onChange={handleInputChange('isCustom')}
                disabled={isLoading}
              />
            </>
          )}
        </PohCol>
      </PohRow>
      <section className="mt-3">
        {addData.type === IQuestionType.Input && (
          <div>
            <h5>Настройки поля ввода</h5>
            <EditQuestionInput
              disabled={isLoading}
              data={(addData as IQuestionInput).params}
              onChange={(up) => handleInputChange<IQuestionInput, 'params'>('params')(up)}
            />
          </div>
        )}
        {addData.type === IQuestionType.Dir && (
          <div>
            <h5>Настройки словаря</h5>
            <EditQuestionDir
              disabled={isLoading}
              data={(addData as IQuestionDir).dir}
              onChange={(up) => handleInputChange<IQuestionDir, 'dir'>('dir')(up)}
            />
          </div>
        )}

        {addData.type === IQuestionType.Select && (
          <div>
            <h5>Варианты</h5>
            <EditQuestionOptions
              disabled={isLoading}
              data={(addData as IQuestionSelect).options}
              onChange={(updatedOptions) =>
                handleInputChange<IQuestionSelect, 'options'>('options')(updatedOptions)
              }
            />
          </div>
        )}
      </section>

      <footer className="text-end pt-2 mb-n3">
        {error && <PohAlert variant={AlertVariant.Danger}>{error.message}</PohAlert>}
        <PohButton type="submit">Сохранить</PohButton>
      </footer>
    </form>
  );
};

export const editQuestion = (data: IQuestion, iv_id: number): Promise<IQuestion> => {
  return new Promise((res) => {
    showModal({
      title: data.id && +data.id > 0 ? 'Редактирование вопроса' : 'Добавление вопроса',
      children: (clos) => (
        <EditQuestion
          data={data}
          iv_id={iv_id}
          onSave={(r) => {
            res(r);
            clos();
          }}
        />
      ),
    });
  });
};
