import React from 'react';

import { IQuestionInputParams } from '@apps/Interview/@types/interview.types';
import {
  allowedInterviewInputTypes,
  inputAsDate,
  inputAsNumber,
  inputAsText,
  inputAsTime,
} from '@apps/Interview/resources/interview.resource';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohSelect from '@ui-kit/Select';

interface IEditQuestionInputProps {
  data: IQuestionInputParams;
  onChange: (data: IQuestionInputParams) => void;
  disabled?: boolean;
}

const EditQuestionInput: React.FC<IEditQuestionInputProps> = ({ data, onChange, disabled }) => {
  const handleInputChange =
    <K extends keyof IQuestionInputParams>(field: keyof IQuestionInputParams) =>
    (value: IQuestionInputParams[K]) => {
      onChange({
        ...data,
        [field]: value,
      });
    };

  return (
    <div>
      <PohSelect
        horizontal
        required
        label="Тип поля"
        options={allowedInterviewInputTypes.map((x) => ({ value: x, label: x }))}
        value={data.type}
        onChange={handleInputChange('type')}
        disabled={disabled}
      />
      <PohInput
        horizontal
        label="Подсказка"
        value={data.placeholder}
        onChange={handleInputChange('placeholder')}
        placeholder="Будет отображать вот так - сереньким"
        disabled={disabled}
      />
      {inputAsText.includes(data.type as InputTypes) && (
        <PohRow>
          <PohCol sm={2} />
          <PohCol sm={6}>
            <PohInput
              label="RegExp"
              value={data.pattern}
              onChange={handleInputChange('pattern')}
              placeholder="RegExp"
              disabled={disabled}
            />
          </PohCol>
          <PohCol sm={4}>
            <PohInput
              label="Макс. длина"
              value={data.max}
              onChange={handleInputChange('max')}
              disabled={disabled}
              type={InputTypes.number}
              max={1023}
            />
          </PohCol>
        </PohRow>
      )}

      {inputAsNumber.includes(data.type as InputTypes) && (
        <PohRow>
          <PohCol sm={2} />
          <PohCol sm={3}>
            <PohInput
              label="min"
              value={data.min}
              onChange={handleInputChange('min')}
              disabled={disabled}
              type={InputTypes.number}
            />
          </PohCol>
          <PohCol sm={3}>
            <PohInput
              label="max"
              value={data.max}
              onChange={handleInputChange('max')}
              disabled={disabled}
              type={InputTypes.number}
            />
          </PohCol>
          <PohCol sm={3}>
            <PohInput
              label="step"
              value={data.step}
              onChange={handleInputChange('step')}
              disabled={disabled}
              type={InputTypes.number}
            />
          </PohCol>
        </PohRow>
      )}

      {inputAsDate.includes(data.type as InputTypes) && (
        <PohRow>
          <PohCol sm={2} />
          <PohCol sm={4}>
            <PohInput
              label="min"
              value={data.min}
              onChange={handleInputChange('min')}
              disabled={disabled}
              type={InputTypes.date}
            />
          </PohCol>
          <PohCol sm={4}>
            <PohInput
              label="max"
              value={data.max}
              onChange={handleInputChange('max')}
              disabled={disabled}
              type={InputTypes.date}
            />
          </PohCol>
        </PohRow>
      )}

      {inputAsTime.includes(data.type as InputTypes) && (
        <PohRow>
          <PohCol sm={4}>
            <PohInput
              label="min"
              value={data.min}
              onChange={handleInputChange('min')}
              disabled={disabled}
              type={InputTypes.time}
            />
          </PohCol>
          <PohCol sm={4}>
            <PohInput
              label="max"
              value={data.max}
              onChange={handleInputChange('max')}
              disabled={disabled}
              type={InputTypes.time}
            />
          </PohCol>
          <PohCol sm={4}>
            <PohInput
              label="step (sec)"
              value={data.step}
              onChange={handleInputChange('step')}
              disabled={disabled}
              type={InputTypes.number}
              min={60}
            />
          </PohCol>
        </PohRow>
      )}
    </div>
  );
};

export default EditQuestionInput;
