import React from 'react';

import { IQuestionSelectParams } from '@apps/Interview/@types/interview.types';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput from '@ui-kit/Input';
import PohList from '@ui-kit/List';

interface IEditQuestionOptionsProps {
  data: IQuestionSelectParams[];
  onChange: (data: IQuestionSelectParams[]) => void;
  disabled?: boolean;
}

const EditQuestionOptions: React.FC<IEditQuestionOptionsProps> = ({ data, onChange, disabled }) => {
  return (
    <div>
      <PohList
        data={data.map((d) => {
          return {
            key: d.value,
            children: (
              <div className="d-flex">
                {d.value}
                <PohButton
                  className="ms-auto"
                  icon={IconsEnum.close}
                  size={ButtonSize.Small}
                  onClick={async () => {
                    onChange(data.filter((x) => x.value !== d.value));
                  }}
                  disabled={disabled}
                />
              </div>
            ),
          };
        })}
      />
      <PohInput
        placeholder="Введите и нажмите Enter чтобы добавить"
        className="mt-2"
        disabled={disabled}
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            e.stopPropagation();
            const order_index = (data.at(-1)?.order_index ?? data.length) + 1;
            const el = e.target as HTMLInputElement;
            const name = el.value.trim();
            if (!name) return;
            if (data.find((x) => x.value === name)) {
              notificationHelper.warn('Уже есть');
              return;
            }

            onChange([...data, { id: 0, value: name, order_index }]);
            el.value = '';
            el.focus();
          }
        }}
        defaultValue=""
      />
    </div>
  );
};

export default EditQuestionOptions;
